"""Misc helpers."""


def chunk_list(items: list, size: int) -> list[list[Any]]:
    return [items[i:i + size] for i in range(0, len(items), size)]


def merge_dicts(*dicts: dict[Any, Any]) -> dict[Any, Any]:
    result = {}
    for d in dicts:
        result.update(d)
    return result


def flatten(nested: list) -> list[Any]:
    result = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result


def unique_preserve_order(items: list) -> list[Any]:
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result


def safe_divide(numerator: float, denominator: float, default: float = 0.0) -> float:
    if denominator == 0:
        return default
    return numerator / denominator
EOF
